typedef unsigned int nlUint32;
typedef nlUint32 nslEmitterId;
typedef float nlVector3d[3];

struct nslEmitter
{
  bool used;
  bool autoRelease;
  bool isALineEmitter;
  char alignment;
  nslEmitterId myId;
  nlVector3d startPosition;
  nlVector3d endPosition;
  nlVector3d position;
  char emittedSounds[24];
};

struct nslSystem
{
  char beforeEmitterSlots[45160];
  nslEmitter emitterSlots[256];
  char beforeOn[16];
  int on;
};

extern nslSystem nsl;
extern void _nslInitialized();
extern void _nslCheckEmitterIdValidity(nslEmitterId checkId);
extern "C" void *memcpy(void *dest, const void *src, unsigned int count);

#define ASSERT_NSL_INITIALIZED() _nslInitialized()
#define ASSERT_EMITTER_ID_VALID(id) _nslCheckEmitterIdValidity(id)
#define NSL_GET_SLOT_FROM_ID(id) ((id) & 0x3ff)

void nslSetEmitterPosition( nslEmitterId emitterToSet, const nlVector3d &newPosition )
{
  if (!nsl.on) return;
  ASSERT_NSL_INITIALIZED();
  ASSERT_EMITTER_ID_VALID(emitterToSet);
  memcpy(nsl.emitterSlots[NSL_GET_SLOT_FROM_ID(emitterToSet)].position, newPosition, sizeof(nlVector3d));
  /*nsl.emitterSlots[NSL_GET_SLOT_FROM_ID(emitterToSet)].position[0] = newPosition[0];
  nsl.emitterSlots[NSL_GET_SLOT_FROM_ID(emitterToSet)].position[1] = newPosition[1];
  nsl.emitterSlots[NSL_GET_SLOT_FROM_ID(emitterToSet)].position[2] = newPosition[2];*/

}
